<?php require dirname(__DIR__,2).'/layouts/admin_start.php'; ?><section class="content-card"><div class="section-heading"><div><h2>Preservantes configurados</h2><p>Cadastre as soluções usadas pelas referências de bolsa e nas regras de validade.</p></div></div><form class="preservative-create" method="post" action="/admin/preservatives"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><label><span>Código</span><input name="code" maxlength="60" required placeholder="Ex.: CPD"></label><label><span>Nome</span><input name="name" maxlength="180" required placeholder="Nome do preservante"></label><input type="hidden" name="active" value="1"><button class="button">Adicionar</button></form><div class="table-wrap"><table><thead><tr><th>Código</th><th>Nome</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($preservatives as $p):?><tr><form method="post" action="/admin/preservatives"><td><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><input class="inline-input" name="code" required maxlength="60" value="<?= htmlspecialchars($p['code']??'') ?>"></td><td><input class="inline-input" name="name" required maxlength="180" value="<?= htmlspecialchars($p['name']) ?>"></td><td><select class="inline-input" name="active"><option value="1" <?= $p['active']?'selected':'' ?>>Ativo</option><option value="0" <?= !$p['active']?'selected':'' ?>>Inativo</option></select></td><td><button class="table-action inline-action">Salvar</button></td></form></tr><?php endforeach;?></tbody></table></div></section><?php require dirname(__DIR__,2).'/layouts/admin_end.php'; ?>
